var checkPalindromeFormation = function(a, b) {
    function isPal(s, i, j) {
        while (i < j) {
            if (s[i] !== s[j]) return false;
            i++;
            j--;
        }
        return true;
    }

    function check(s1, s2) {
        let i = 0, j = s1.length - 1;
        while (i < j && s1[i] === s2[j]) {
            i++;
            j--;
        }
        if (i >= j) return true;
        return isPal(s1, i, j) || isPal(s2, i, j);
    }

    return check(a, b) || check(b, a);
